474	export const AppSidebar = React.memo(function AppSidebar({
475	    ...props
476	}: React.ComponentProps<typeof Sidebar>) {
477	    // ==================
478	    // # Store
479	    // ==================
480	    const permissions = useUserInfoStore((state) => state.permissions);
481	    const dataUser = useUserInfoStore((state) => state.data);
482	    const isUserLoading = useUserInfoStore((state) => state.isUserLoading);
483	    const isPermissionsLoading = useUserInfoStore((state) => state.isPermissionsLoading);
484	    const isVisitorMode = useVisitorMode();
485	
486	    // ==================
487	    // # Context
488	    // ==================
489	    const { modalOpen, setModalOpen } = React.useContext(DefaultLayoutContext);
490	
491	    // ==================
492	    // # Constants
493	    // ==================
494	    const pathname = usePathname();
495	    const tenant = getTenantFromUrl();
496	    const isFromBuriti = tenant === 'buriti';
497	    const isFromCeler = tenant === 'celer';
498	    const isFromMd = tenant === 'md';
499	    const isFromDasi = tenant === 'dasi';
500	    const role = dataUser.role;
501	    const isInvestor = typeof role === 'string' && role.startsWith('INVESTIDOR');
502	    const disableCountsWs = isVisitorMode || role === 'COMERCIAL_BROKER' || isInvestor;
503	    const canViewDueDiligence2 = canAccessDueDiligence2({
504	        permissions,
505	        role,
506	        isSuperuser: dataUser.is_superuser,
507	    });
508	    const canViewBrokerV4 = isBrokerV4Enabled(permissions);
509	    const showDueDiligence2Sidebar = shouldShowDueDiligence2Sidebar({
510	        canViewDueDiligence2,
511	        brokerV4Enabled: canViewBrokerV4,
512	        role,
513	    });
514	    const showMeusOficiosSidebar = !isBrokerV4OficiosCutover({
515	        brokerV4Enabled: canViewBrokerV4,
516	        role,
517	    });
518	
519	    const isCommandPaletteOpen = useCommandPaletteStore((state) => state.isOpen);
520	    const setIsCommandPaletteOpen = useCommandPaletteStore((state) => state.setOpen);
521	    const {
522	        isOpen: isSupportOpen,
523	        openModal: openSupportModal,
524	        closeModal: closeSupportModal,
525	    } = useSupportModalStore();
526	
527	    useCloseMobileSidebarOnPathnameChange();
528	
529	    // ==================
530	    // # Changelog
531	    // ==================
532	    const { hasUnread, markAsRead } = useChangelogNotification();
533	
534	    // ==================
535	    // # Effects
536	    // ==================
537	    const canViewGlobalSearch = canAccessGlobalSearch(permissions);
538	    const canCreatePrecatorio = Boolean(
539	        permissions?.includes(Permissions.VIEW_NOVO_PRECATORIO_MODAL),
540	    );
541	
542	    React.useEffect(() => {
543	        const down = (e: KeyboardEvent) => {
544	            if (e.key === 'k' && (e.metaKey || e.ctrlKey)) {
545	                e.preventDefault();
546	                useCommandPaletteStore.getState().togglePalette('keyboard');
547	            }
548	        };
549	
550	        document.addEventListener('keydown', down);
551	        return () => document.removeEventListener('keydown', down);
552	    }, []);
553	
554	    const { data: accessibleHosts } = useQuery({
555	        queryKey: [QueryKeys.host.accessible],
556	        queryFn: getAccessibleHosts,
557	        staleTime: 5 * 60 * 1000,
558	        enabled: !isVisitorMode,
559	    });
560	    const currentHostPlan = React.useMemo(() => {
561	        const host = accessibleHosts?.find((h) => h.domain === tenant);
562	        if (!host) return 'Pro';
563	        return host.is_delegate ? 'Pro' : 'Enterprise';
564	    }, [accessibleHosts, tenant]);
565	
566	    const { counts, isLoading: isCountsLoading } = useSidebarCounts({ disabled: disableCountsWs });
567	    const { counts: dueCounts, isLoading: isDueCountsLoading } = useDueDashboardCounts({
568	        disabled: disableCountsWs,
569	        userRole: role,
570	        permissions,
571	    });
572	    const dueDiligence2SidebarCounts = useDueDiligence2SidebarCounts({
573	        userRole: role,
574	        userUsername: dataUser.user,
575	        enabled: canViewDueDiligence2,
576	    });
577	    const pendenciasBadge =
578	        !isCountsLoading && (counts?.pendencias || 0) > 0 ? counts?.pendencias : undefined;
579	    const repactuacoesBadge =
580	        !isCountsLoading && (counts?.repactuacoes || 0) > 0 ? counts?.repactuacoes : undefined;
581	    const juridicoTotal = !isDueCountsLoading
582	        ? (dueCounts.todos ??
583	          Object.values(dueCounts.juridico || {}).reduce((acc, curr) => acc + (curr || 0), 0))
584	        : undefined;
585	    const finalizacaoTotal = !isDueCountsLoading
586	        ? (dueCounts.liquidacao_cessao_total ??
587	          Object.values(dueCounts.finalizacao || {}).reduce((acc, curr) => acc + (curr || 0), 0))
588	        : undefined;
589	
590	    const isB2COperator = isDedicatedB2COperatorRole(role);
591	
592	    const canViewDashboard =
593	        tenant === 'celer' &&
594	        (dataUser.role === 'MASTER' ||
595	            dataUser.role === 'COMERCIAL_COORDENADOR' ||
596	            dataUser.role === 'COMERCIAL_COORDENADOR_EXTERNO' ||
597	            isB2COperator ||
598	            permissions?.includes(Permissions.VIEW_LEADS));
599	
600	    const canAccessOperationalTriggers = useCanAccessOperationalTriggersScreen({
601	        host: dataUser.host,
602	        role,
603	        isSuperuser: dataUser.is_superuser,
604	    });
605	    const uniflowAccessInput = {
606	        role,
607	        isSuperuser: dataUser.is_superuser,
608	        permissions,
609	    };
610	    const canViewFinanceiro = hasOperacoesFinanceirasAccess(uniflowAccessInput);
611	    const canViewCartorios = hasCartoriosAccess(role);
612	    const canViewUniflowExtended = canViewUniflowItemsBeyondCartorios(uniflowAccessInput);
613	    const canViewCrmOperacional = canViewUniflowCrm(uniflowAccessInput);
614	    const canViewUniflowSalas =
615	        canViewUniflowExtended || canViewUniflowMeetingRooms(uniflowAccessInput);
616	    const canViewUniflow =
617	        !isFromDasi &&
618	        (canViewUniflowSection(uniflowAccessInput) ||
619	            canViewCartorios ||
620	            canViewFinanceiro ||
621	            canViewCrmOperacional);
622	
623	    const canViewExportacoes = canAccessExportacoesPage({ permissions, role });
624	
625	    const canViewGerencialBrokerUsers = canAccessGerencialBrokerUsersNav({
626	        permissions,
627	        role,
628	        isSuperuser: dataUser.is_superuser,
629	    });
630	
631	    const data = React.useMemo(
632	        () => ({
633	            teams: [
634	                {
635	                    name: tenant.charAt(0).toUpperCase() + tenant.slice(1),
636	                    logo: Logo as React.ElementType,
637	                    plan: currentHostPlan,
638	                },
639	            ],
640	            navMain: [
641	                {
642	                    title: 'Resumo do Dia',
643	                    url: APP_ROUTES.private.now.name,
644	                    icon: Zap,
645	                    isActive: pathname === APP_ROUTES.private.now.name,
646	                    when:
647	                        !isFromDasi &&
648	                        role !== 'INVESTIDOR_WALLET' &&
649	                        permissions?.includes(Permissions.VIEW_DAILY_BRIEFING),
650	                },
651	                {
652	                    title: 'Ativos Intelligence',
653	                    url: APP_ROUTES.private.ativosIntelligence.name,
654	                    icon: Sparkles,
655	                    isActive: pathname === APP_ROUTES.private.ativosIntelligence.name,
656	                    when:
657	                        !isFromDasi &&
658	                        permissions?.includes(Permissions.VIEW_ATIVOS_INTELLIGENCE_CHAT),
659	                },
660	                {
661	                    title: 'Compliance',
662	                    url: '#',
663	                    icon: Shield,
664	                    isActive: pathname.startsWith('/compliance'),
665	                    when: canViewComplianceNavSection(permissions),
666	                    items: [
667	                        {
668	                            title: 'Canal de Denúncias',
669	                            url: APP_ROUTES.private.canalDenuncias.name,
670	                            isActive:
