export const AppSidebar = React.memo(function AppSidebar({
    ...props
}: React.ComponentProps<typeof Sidebar>) {
    // ==================
    // # Store
    // ==================
    const permissions = useUserInfoStore((state) => state.permissions);
    const dataUser = useUserInfoStore((state) => state.data);
    const isUserLoading = useUserInfoStore((state) => state.isUserLoading);
    const isPermissionsLoading = useUserInfoStore((state) => state.isPermissionsLoading);
    const isVisitorMode = useVisitorMode();

    // ==================
    // # Context
    // ==================
    const { modalOpen, setModalOpen } = React.useContext(DefaultLayoutContext);

    // ==================
    // # Constants
    // ==================
    const pathname = usePathname();
    const tenant = getTenantFromUrl();
    const isFromBuriti = tenant === 'buriti';
    const isFromCeler = tenant === 'celer';
    const isFromMd = tenant === 'md';
    const isFromDasi = tenant === 'dasi';
    const role = dataUser.role;
    const isInvestor = typeof role === 'string' && role.startsWith('INVESTIDOR');
    const disableCountsWs = isVisitorMode || role === 'COMERCIAL_BROKER' || isInvestor;
    const canViewDueDiligence2 = canAccessDueDiligence2({
        permissions,
        role,
        isSuperuser: dataUser.is_superuser,
    });
    const canViewBrokerV4 = isBrokerV4Enabled(permissions);
    const showDueDiligence2Sidebar = shouldShowDueDiligence2Sidebar({
        canViewDueDiligence2,
        brokerV4Enabled: canViewBrokerV4,
        role,
    });
    const showMeusOficiosSidebar = !isBrokerV4OficiosCutover({
        brokerV4Enabled: canViewBrokerV4,
        role,
    });

    const isCommandPaletteOpen = useCommandPaletteStore((state) => state.isOpen);
    const setIsCommandPaletteOpen = useCommandPaletteStore((state) => state.setOpen);
    const {
        isOpen: isSupportOpen,
        openModal: openSupportModal,
        closeModal: closeSupportModal,
    } = useSupportModalStore();

    useCloseMobileSidebarOnPathnameChange();

    // ==================
    // # Changelog
    // ==================
    const { hasUnread, markAsRead } = useChangelogNotification();

    // ==================
    // # Effects
    // ==================
    const canViewGlobalSearch = canAccessGlobalSearch(permissions);
    const canCreatePrecatorio = Boolean(
        permissions?.includes(Permissions.VIEW_NOVO_PRECATORIO_MODAL),
    );

    React.useEffect(() => {
        const down = (e: KeyboardEvent) => {
            if (e.key === 'k' && (e.metaKey || e.ctrlKey)) {
                e.preventDefault();
                useCommandPaletteStore.getState().togglePalette('keyboard');
            }
        };

        document.addEventListener('keydown', down);
        return () => document.removeEventListener('keydown', down);
    }, []);

    const { data: accessibleHosts } = useQuery({
        queryKey: [QueryKeys.host.accessible],
        queryFn: getAccessibleHosts,
        staleTime: 5 * 60 * 1000,
        enabled: !isVisitorMode,
    });
    const currentHostPlan = React.useMemo(() => {
        const host = accessibleHosts?.find((h) => h.domain === tenant);
        if (!host) return 'Pro';
        return host.is_delegate ? 'Pro' : 'Enterprise';
    }, [accessibleHosts, tenant]);

    const { counts, isLoading: isCountsLoading } = useSidebarCounts({ disabled: disableCountsWs });
    const { counts: dueCounts, isLoading: isDueCountsLoading } = useDueDashboardCounts({
        disabled: disableCountsWs,
        userRole: role,
        permissions,
    });
    const dueDiligence2SidebarCounts = useDueDiligence2SidebarCounts({
        userRole: role,
        userUsername: dataUser.user,
        enabled: canViewDueDiligence2,
    });
    const pendenciasBadge =
        !isCountsLoading && (counts?.pendencias || 0) > 0 ? counts?.pendencias : undefined;
    const repactuacoesBadge =
        !isCountsLoading && (counts?.repactuacoes || 0) > 0 ? counts?.repactuacoes : undefined;
    const juridicoTotal = !isDueCountsLoading
        ? (dueCounts.todos ??
          Object.values(dueCounts.juridico || {}).reduce((acc, curr) => acc + (curr || 0), 0))
        : undefined;
    const finalizacaoTotal = !isDueCountsLoading
        ? (dueCounts.liquidacao_cessao_total ??
          Object.values(dueCounts.finalizacao || {}).reduce((acc, curr) => acc + (curr || 0), 0))
        : undefined;

    const isB2COperator = isDedicatedB2COperatorRole(role);

    const canViewDashboard =
        tenant === 'celer' &&
        (dataUser.role === 'MASTER' ||
            dataUser.role === 'COMERCIAL_COORDENADOR' ||
            dataUser.role === 'COMERCIAL_COORDENADOR_EXTERNO' ||
            isB2COperator ||
            permissions?.includes(Permissions.VIEW_LEADS));

    const canAccessOperationalTriggers = useCanAccessOperationalTriggersScreen({
        host: dataUser.host,
        role,
        isSuperuser: dataUser.is_superuser,
    });
    const uniflowAccessInput = {
        role,
        isSuperuser: dataUser.is_superuser,
        permissions,
    };
    const canViewFinanceiro = hasOperacoesFinanceirasAccess(uniflowAccessInput);
    const canViewCartorios = hasCartoriosAccess(role);
    const canViewUniflowExtended = canViewUniflowItemsBeyondCartorios(uniflowAccessInput);
    const canViewCrmOperacional = canViewUniflowCrm(uniflowAccessInput);
    const canViewUniflowSalas =
        canViewUniflowExtended || canViewUniflowMeetingRooms(uniflowAccessInput);
    const canViewUniflow =
        !isFromDasi &&
        (canViewUniflowSection(uniflowAccessInput) ||
            canViewCartorios ||
            canViewFinanceiro ||
            canViewCrmOperacional);

    const canViewExportacoes = canAccessExportacoesPage({ permissions, role });

    const canViewGerencialBrokerUsers = canAccessGerencialBrokerUsersNav({
        permissions,
        role,
        isSuperuser: dataUser.is_superuser,
    });

    const data = React.useMemo(
        () => ({
            teams: [
                {
                    name: tenant.charAt(0).toUpperCase() + tenant.slice(1),
                    logo: Logo as React.ElementType,
                    plan: currentHostPlan,
                },
            ],
            navMain: [
                {
                    title: 'Resumo do Dia',
                    url: APP_ROUTES.private.now.name,
                    icon: Zap,
                    isActive: pathname === APP_ROUTES.private.now.name,
                    when:
                        !isFromDasi &&
                        role !== 'INVESTIDOR_WALLET' &&
                        permissions?.includes(Permissions.VIEW_DAILY_BRIEFING),
                },
                {
                    title: 'Ativos Intelligence',
                    url: APP_ROUTES.private.ativosIntelligence.name,
                    icon: Sparkles,
                    isActive: pathname === APP_ROUTES.private.ativosIntelligence.name,
                    when:
                        !isFromDasi &&
                        permissions?.includes(Permissions.VIEW_ATIVOS_INTELLIGENCE_CHAT),
                },
                {
                    title: 'Compliance',
                    url: '#',
                    icon: Shield,
                    isActive: pathname.startsWith('/compliance'),
                    when: canViewComplianceNavSection(permissions),
                    items: [
                        {
                            title: 'Canal de Denúncias',
                            url: APP_ROUTES.private.canalDenuncias.name,
                            isActive:
                                pathname.startsWith(APP_ROUTES.private.canalDenuncias.name) &&
                                !pathname.startsWith(
                                    APP_ROUTES.private.canalDenunciasTriagem.name,
                                ) &&
                                !pathname.startsWith(APP_ROUTES.private.canalDenunciasAudit.name),
                            when: canViewCanalDenunciasNav(permissions),
                        },
                        {
                            title: 'Triagem neutra',
                            url: APP_ROUTES.private.canalDenunciasTriagem.name,
                            isActive: pathname.startsWith(
                                APP_ROUTES.private.canalDenunciasTriagem.name,
                            ),
                            when: canViewTriagemNeutraNav(permissions),
                        },
                        {
                            title: 'Auditoria',
                            url: APP_ROUTES.private.canalDenunciasAudit.name,
                            isActive: pathname.startsWith(
                                APP_ROUTES.private.canalDenunciasAudit.name,
                            ),
                            when: canViewAuditNav(permissions),
                        },
                    ],
                },
                {
                    title: 'Uniflow',
                    url: '#',
                    icon: UniflowIcon,
                    isActive: pathname.includes('/uniflow'),
                    when: canViewUniflow,
                    items: [
                        {
                            title: 'CRM Operacional',
                            url: APP_ROUTES.private.uniflowCrm.name,
                            when: canViewCrmOperacional,
                        },
                        {
                            title: 'Operações',
                            url: APP_ROUTES.private.uniflowFinanceiro.name,
                            when: canViewUniflowExtended,
                        },
                        {
                            title: 'Operações Financeiras',
                            url: '/uniflow/operacoes-financeiras',
                            when: canViewFinanceiro,
                        },
                        {
                            title: 'Cartórios',
                            url: '/uniflow/cartorios',
                            when: canViewCartorios,
                        },
                        {
                            title: 'Pipeline',
                            url: APP_ROUTES.private.uniflowPipeline.name,
                            disabled: true,
                            badge: 'PREVISTO',
                            when: canViewUniflowExtended,
                        },
                        {
                            title: 'Salas',
                            url: APP_ROUTES.private.uniflowSalas.name,
                            badge: <MeetingRoomsSidebarStatus />,
                            when: canViewUniflowSalas,
                        },
                    ],
                },
                {
                    title: 'CRM',
                    url: '#',
                    icon: BriefcaseBusiness,
                    isActive:
                        pathname.startsWith('/crm/dashboard') ||
                        pathname.startsWith('/crm/tarefas') ||
                        pathname === APP_ROUTES.private.calculator.name,
                    when: !isVisitorMode && !isFromDasi,
                    items: [
                        {
                            title: getB2CSidebarDashboardTitle(role),
                            url: APP_ROUTES.private.dashboard.name,
                            when: canViewDashboard,
                        },
                        {
                            title: 'Calculadora',
                            url: APP_ROUTES.private.calculator.name,
                            when:
                                !isVisitorMode &&
                                (isFromBuriti || canAccessB2CCalculator(role, permissions)),
                        },
                        {
                            title: 'Meu espaço',
                            url: APP_ROUTES.private.broker.name,
                            // Com a flag do Broker 4.0 o Início substitui o Meu espaço.
                            when:
                                role !== 'MASTER' &&
                                !permissions?.includes(Permissions.VIEW_DASHBOARD_BROKER_V4) &&
                                (permissions?.includes(Permissions.VIEW_DASHBOARD_BROKER) ||
                                    permissions?.includes(
                                        Permissions.VIEW_DASHBOARD_DETALHADO_BROKER,
                                    )) &&
                                (!permissions?.includes(Permissions.VIEW_DASHBOARD_JURIDICO) ||
                                    role === 'COMERCIAL_CLOSER'),
                        },
                        {
                            title: 'Minha operação',
                            url: APP_ROUTES.private.minhaOperacao.name,
                            // Broker 4.0: cockpit que substitui o /now para o broker.
                            // O gate da rota exige role de broker — sem ele o item seria
                            // um link morto para staff com a flag v4.
                            when:
                                role !== 'MASTER' &&
                                canAccessMinhaOperacao({
                                    role,
                                    permissions,
                                    isSuperuser: dataUser.is_superuser,
                                }),
                        },
                        {
                            title: 'Início',
                            url: APP_ROUTES.private.brokerInicio.name,
                            // Broker 4.0: só com a flag de cutover (host + usuário); sem ela, só o Meu espaço.
                            when:
                                role !== 'MASTER' &&
                                permissions?.includes(Permissions.VIEW_DASHBOARD_BROKER_V4) &&
                                (permissions?.includes(Permissions.VIEW_DASHBOARD_BROKER) ||
                                    permissions?.includes(
                                        Permissions.VIEW_DASHBOARD_DETALHADO_BROKER,
                                    )) &&
                                (!permissions?.includes(Permissions.VIEW_DASHBOARD_JURIDICO) ||
                                    role === 'COMERCIAL_CLOSER'),
                        },
                        {
                            title: 'Gerencial Broker',
                            url:
                                role === 'MASTER' || role === 'COMERCIAL_COORDENADOR'
                                    ? `${APP_ROUTES.private.gerencialBroker.name}?${role === 'MASTER' ? 'coordenador=all&criado_por=all' : 'criado_por=all'}`
                                    : APP_ROUTES.private.gerencialBroker.name,

                            when: role === 'MASTER' || role === 'COMERCIAL_COORDENADOR',
                            // (permissions?.includes(Permissions.VIEW_DASHBOARD_BROKER) ||
                            //     permissions?.includes('
                            //         Permissions.VIEW_DASHBOARD_DETALHADO_BROKER,
                            //     )) &&
                            // !permissions?.includes(Permissions.VIEW_DASHBOARD_JURIDICO),
                        },
                        {
                            title: 'Meus Ofícios',
                            url: APP_ROUTES.private.oficios.name,
                            // Broker 4.0: o Início absorve a lista; o item some para roles de broker.
                            when:
                                !isFromBuriti &&
                                showMeusOficiosSidebar &&
                                permissions?.includes(Permissions.VIEW_MEUS_OFICIOS),
                        },
                        {
                            title: 'Propostas digitais',
                            url: APP_ROUTES.private.propostasDigitais.name,
                            when:
                                role !== 'MASTER' &&
                                (permissions?.includes(Permissions.VIEW_DASHBOARD_BROKER) ||
                                    permissions?.includes(
                                        Permissions.VIEW_DASHBOARD_DETALHADO_BROKER,
                                    )),
                        },
                        {
                            title: 'Extrato de comissão',
                            url: APP_ROUTES.private.extratoComissao.name,
                            when: role !== 'MASTER' && canViewBrokerV4,
                        },
                        {
                            title: 'Pendências e Repactuações',
                            url: APP_ROUTES.private.brokerPendenciasRepactuacoes.name,
                            when: role !== 'MASTER' && canViewBrokerV4,
                        },

                        {
                            title: 'Tarefas',
                            url: APP_ROUTES.private.tarefas.name,
                            when:
                                !isVisitorMode &&
                                (!isB2COperator || permissions?.includes(Permissions.VIEW_LEADS)),
                        },
                    ],
                },
                {
                    title: 'Jurídico',
                    url: '#',
                    icon: Scale,
                    isActive: pathname.includes('/juridico'),
                    when:
                        !isFromBuriti &&
                        (permissions?.includes(Permissions.VIEW_DASHBOARD_JURIDICO) ||
                            permissions?.includes(Permissions.VIEW_POS_AQUISICAO) ||
                            permissions?.includes(Permissions.MANAGE_CESSIONARIOS) ||
                            permissions?.includes(Permissions.PARTNER_FEED_MANAGE)),
                    items: [
                        {
                            title: 'Due-Diligence',
                            url: APP_ROUTES.private.dueDiligence.name,
                            badge: juridicoTotal && juridicoTotal > 0 ? juridicoTotal : undefined,
                            when:
                                !isFromDasi &&
                                permissions?.includes(Permissions.VIEW_DASHBOARD_JURIDICO),
                        },
                        {
                            title: 'Liquidação/Cessão',
                            url: APP_ROUTES.private.liquidacaoCessao.name,
                            badge:
                                finalizacaoTotal && finalizacaoTotal > 0
                                    ? finalizacaoTotal
                                    : undefined,
                            when:
                                !isFromDasi &&
                                permissions?.includes(Permissions.VIEW_DASHBOARD_JURIDICO),
                        },
                        {
                            title: 'Cessionários',
                            url: APP_ROUTES.private.cessionarios.name,
                            when:
                                !isFromDasi &&
                                (permissions?.includes(Permissions.MANAGE_CESSIONARIOS) ||
                                    role?.toUpperCase() === 'MASTER'),
                        },
                        {
                            title: 'Parceiros',
                            url: APP_ROUTES.private.parceiros.name,
                            isActive: pathname.includes('/juridico/parceiros'),
                            when:
                                !isFromDasi &&
                                (permissions?.includes(Permissions.MANAGE_CESSIONARIOS) ||
                                    permissions?.includes(Permissions.PARTNER_FEED_MANAGE) ||
                                    role?.toUpperCase() === 'MASTER'),
                        },
                        {
                            title: 'Pós-Aquisição',
                            url: APP_ROUTES.private.newPosPrecatorio.name,
                            isActive: pathname.includes('/juridico/pos-aquisicao'),
                            when:
                                !isFromMd && permissions?.includes(Permissions.VIEW_POS_AQUISICAO),
                            // items: [
                            //     {
                            //         title: 'Precatórios',
                            //         url: APP_ROUTES.private.posPrecatorio.name,
                            //     },
                            // {
                            //     title: 'Processos Judiciais',
                            //     url: APP_ROUTES.private.procJud.name,
                            // },
                            // {
                            //     title: 'New Pós',
                            //     url: APP_ROUTES.private.newPosPrecatorio.name,
                            // },
                            // ],
                        },
                    ],
                },
                {
                    title: 'Relatórios',
                    url: '#',
                    icon: FileSpreadsheet,
                    isActive: pathname.includes('/relatorios'),
                    // MASTER continua com acesso irrestrito; coordenador comercial entra
                    // só pela permission de exportações (item abaixo tem o mesmo gate).
                    when: isFromCeler && (role === 'MASTER' || canViewExportacoes),
                    items: [
                        {
                            title: 'Exportações',
                            url: APP_ROUTES.private.exportacoes.name,
                            when: canViewExportacoes,
                        },
                        {
                            title: 'Monitoramento Calculadora',
                            url: APP_ROUTES.private.monitoramentoCalculadora.name,
                            when: role === 'MASTER' && dataUser?.is_staff,
                        },
                        {
                            title: 'Gatilhos Operacionais',
                            url: APP_ROUTES.private.gatilhosOperacionais.name,
                            when: canAccessOperationalTriggers,
                        },
                    ],
                },
                {
                    title: 'Comercial',
                    url: '#',
                    icon: LayoutDashboard,
                    isActive: pathname.includes('/comercial'),
                    when:
                        canViewGerencialBrokerUsers ||
                        permissions?.includes(Permissions.VIEW_DASHBOARD_JURIDICO) ||
                        permissions?.includes(Permissions.MANAGE_DOCUMENTS),
                    items: [
                        {
                            title: 'Usuários',
                            url: `${APP_ROUTES.private.gerencialBroker.name}?tab=users`,
                            when: canViewGerencialBrokerUsers,
                        },
                        {
                            title: 'Pendências',
                            url: APP_ROUTES.private.comercialPendencias.name,
                            when:
                                !isFromDasi &&
                                permissions?.includes(Permissions.VIEW_DASHBOARD_JURIDICO),
                            badge: pendenciasBadge,
                        },
                        {
                            title: 'Repactuações',
                            url: APP_ROUTES.private.comercialRepactuacoes.name,
                            when:
                                !isFromDasi &&
                                permissions?.includes(Permissions.VIEW_DASHBOARD_JURIDICO),
                            badge: repactuacoesBadge,
                        },
                        {
                            title: 'Aprovação de Documentos',
                            url: APP_ROUTES.private.comercialAprovacaoDocumentos.name,
                            when:
                                !isFromDasi && permissions?.includes(Permissions.MANAGE_DOCUMENTS),
                        },
                    ],
                },
                {
                    title: 'Novidades',
                    url: APP_ROUTES.public.changelog.name,
                    icon: Sparkles,
                    badge: hasUnread ? '●' : undefined,
                    onClick: markAsRead,
                    when: !isVisitorMode,
                },
                {
                    title: 'Novas Features',
                    url: '#',
                    icon: FlaskConical,
                    isActive: pathname.includes(APP_ROUTES.private.dueDiligence2.name),
                    when: !isFromBuriti && !isFromDasi && showDueDiligence2Sidebar,
                    items: [
                        {
                            title:
                                role === 'COMERCIAL_BROKER'
                                    ? 'Pendências e Repactuações'
                                    : 'Due Diligence 2.0',
                            url: APP_ROUTES.private.dueDiligence2.name,
                            isActive: pathname.includes(APP_ROUTES.private.dueDiligence2.name),
                            badge: dueDiligence2SidebarCounts.shouldShowBadge ? (
                                <DueDiligence2SidebarBadge
                                    total={dueDiligence2SidebarCounts.total}
                                    breakdown={dueDiligence2SidebarCounts.breakdown}
                                    isComercialRestricted={
                                        dueDiligence2SidebarCounts.isComercialRestricted
                                    }
                                />
                            ) : undefined,
                            when: showDueDiligence2Sidebar,
                        },
                    ],
                },
            ],
            modules: [
                {
                    name: 'Novo Precatório',
                    logo: Plus,
                    fn: () => setModalOpen(!modalOpen),
                },
            ],
        }),
        [
            tenant,
            permissions,
            modalOpen,
            setModalOpen,
            pathname,
            counts,
            isCountsLoading,
            dueCounts,
            isDueCountsLoading,
            currentHostPlan,
            role,
            dataUser.role,
            dataUser.is_superuser,
            canViewDueDiligence2,
            showDueDiligence2Sidebar,
            canViewBrokerV4,
            showMeusOficiosSidebar,
            dueDiligence2SidebarCounts,
            canViewUniflow,
            canViewFinanceiro,
            canViewCartorios,
            canViewUniflowExtended,
            canViewCrmOperacional,
            canViewUniflowSalas,
            canViewGerencialBrokerUsers,
            isVisitorMode,
        ],
    );

    const sidebarPins = useUserPreferencesStore(
        (state) => state.preferences.sidebar.nav?.pins ?? EMPTY_SIDEBAR_PINS,
    );
    const pruneSidebarPins = useUserPreferencesStore((state) => state.pruneSidebarPins);

    const isSidebarReady = Boolean(!isUserLoading && !isPermissionsLoading && dataUser?.role);

    const pinnedNavItems = React.useMemo(
        () => (isSidebarReady ? resolvePinnedItems(sidebarPins, data.navMain) : []),
        [isSidebarReady, sidebarPins, data.navMain],
    );

    const sidebarContentRef = React.useRef<HTMLDivElement>(null);
    useSidebarProximity(sidebarContentRef);

    React.useEffect(() => {
        if (!isSidebarReady || sidebarPins.length === 0) return;
        const validIds = collectPinnableNavItems(data.navMain).map((item) => item.id);
        pruneSidebarPins(validIds);
    }, [isSidebarReady, sidebarPins, data.navMain, pruneSidebarPins]);

    // Modo visitante: sem sessão, as permissões nunca carregam; a sidebar real aparece mesmo assim.
    if (!isVisitorMode && (isUserLoading || isPermissionsLoading || !dataUser?.role)) {
        return (
            <>
                <AppSidebarSkeleton {...props} />
                <CommandPalette
                    open={isCommandPaletteOpen}
                    onOpenChange={setIsCommandPaletteOpen}
                    navItems={[]}
                    canAccessGlobalSearch={false}
                    canCreatePrecatorio={false}
                    onCreatePrecatorio={() => undefined}
                    onOpenSupport={() => openSupportModal()}
                />
            </>
        );
    }

    return (
        <>
            <Sidebar collapsible="icon" {...props}>
                <SidebarCollapseAnalytics />
                <SidebarHeader>
                    <TeamSwitcher teams={data.teams} />
                </SidebarHeader>
                <SidebarContent
                    ref={sidebarContentRef}
                    className="gap-1 overflow-x-hidden overflow-y-auto overscroll-contain"
                >
                    {!isVisitorMode &&
                        permissions?.includes(Permissions.VIEW_NOVO_PRECATORIO_MODAL) && (
                            <NavModule items={data.modules} />
                        )}
                    {!isVisitorMode && <NavPins items={pinnedNavItems} />}
                    {isVisitorMode ? <NavVisitorPlatform /> : <NavMain items={data.navMain} />}
                </SidebarContent>

                <SidebarFooter>
                    <SidebarMenu>
                        {!isVisitorMode && (
                            <SidebarMenuItem>
                                <CrmHelpMenu />
                            </SidebarMenuItem>
                        )}
                        {!isVisitorMode && <Separator className="my-1" />}
                        {isVisitorMode ? <NavVisitorSignup /> : <NavUser user={dataUser} />}
                    </SidebarMenu>
                </SidebarFooter>
                <SidebarRail />
            </Sidebar>
            {modalOpen && !isVisitorMode && <NewForm />}
            {!isVisitorMode && (
                <CommandPalette
                    open={isCommandPaletteOpen}
                    onOpenChange={setIsCommandPaletteOpen}
                    navItems={data.navMain}
                    canAccessGlobalSearch={canViewGlobalSearch}
                    canCreatePrecatorio={canCreatePrecatorio}
                    onCreatePrecatorio={() => setModalOpen(true)}
                    onOpenSupport={() => openSupportModal()}
                />
            )}
            {!isVisitorMode && (
                <SupportModal
                    open={isSupportOpen}
                    onOpenChange={(v) => (v ? openSupportModal() : closeSupportModal())}
                />
            )}
        </>
    );
});

