import { expect } from '@jest/globals';
import { Permissions } from '@/enums/permissions.enum';

import { canAccessGlobalSearch, enabledGlobalSearchSections } from '../global-search-access';

describe('global-search-access', () => {
    it('libera com view_proposal_search', () => {
        expect(canAccessGlobalSearch([Permissions.VIEW_PROPOSAL_SEARCH])).toBe(true);
    });

    it('libera com due (dashboard jurídico ou broker due 2)', () => {
        expect(canAccessGlobalSearch([Permissions.VIEW_DASHBOARD_JURIDICO])).toBe(true);
        expect(canAccessGlobalSearch([Permissions.VIEW_BROKER_DUE_DILIGENCE_2])).toBe(true);
    });

    it('libera com pós-aquisição', () => {
        expect(canAccessGlobalSearch([Permissions.VIEW_POS_AQUISICAO])).toBe(true);
    });

    it('lista seções habilitadas para chips', () => {
        expect(enabledGlobalSearchSections([Permissions.VIEW_PROPOSAL_SEARCH])).toEqual([
            'propostas',
        ]);
        expect(
            enabledGlobalSearchSections([
                Permissions.VIEW_PROPOSAL_SEARCH,
                Permissions.VIEW_DASHBOARD_JURIDICO,
                Permissions.VIEW_POS_AQUISICAO,
            ]),
        ).toEqual(['propostas', 'due', 'pos']);
    });

    it('nega sem nenhuma seção', () => {
        expect(canAccessGlobalSearch([Permissions.READ, 'view_crm_universal'])).toBe(false);
        expect(canAccessGlobalSearch([])).toBe(false);
        expect(canAccessGlobalSearch(null)).toBe(false);
        expect(enabledGlobalSearchSections([])).toEqual([]);
    });
});

